#!/usr/bin/env node
/**
 * One-off warmup injector. Warmups are NOT regenerated by the build —
 * lesson configs are the source of truth once written (see
 * scripts/soften-unit1-warmups.mjs). This file must still be safe to run:
 * a stale hardcoded lesson list previously omitted 23 whole-group lessons
 * that exist on disk and named 7 that do not, so a re-run would have
 * pointed those warmups at the wrong previous lesson (or at themselves).
 *
 * Sequence is derived from whole-group folders on disk, sorted by unit then
 * lesson number — Reveal Math order inside the book, not district pacing
 * order. District pacing is the wrong previous-lesson for a warmup: Unit 5
 * still reviews 5-7 before 5-8 even when the district teaches Unit 5 in spring.
 *
 * Default is --check (report-only). Pass --write to mutate. On-disk warmups
 * are authored once written (spirals, softened Unit 1, catch-up retargets).
 */
import { existsSync, readdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const BANK_PATH = join(ROOT, "spiral-review", "bank.json");
const LESSONS_DIR = join(ROOT, "lessons");

/** Whole-group lesson ids that actually exist on disk, in book order. */
export function wholeGroupLessonIds(lessonsDir = LESSONS_DIR) {
  return readdirSync(lessonsDir)
    .filter((d) => existsSync(join(lessonsDir, d, "config.json")) && /^\d+-\d+$/.test(d))
    .sort((a, b) => {
      const [au, al] = a.split("-").map(Number);
      const [bu, bl] = b.split("-").map(Number);
      return au - bu || al - bl;
    });
}

export function previousLessonId(ids, baseId) {
  const idx = ids.indexOf(baseId);
  if (idx > 0) return ids[idx - 1];
  return baseId;
}

export function getBaseLessonId(folderName) {
  const m = String(folderName).match(/^(\d+-\d+)/);
  return m ? m[1] : folderName;
}

function pickWarmupQuestions(questionsByLesson, questions, prevLessonId, currentLessonId) {
  const pool = questionsByLesson[prevLessonId] || questionsByLesson[currentLessonId] || questions;
  let candidates = pool.filter((q) => q.tier === "approaching" || q.tier === "on-level");
  if (candidates.length < 3) candidates = pool;

  let seed = 0;
  for (let i = 0; i < currentLessonId.length; i++) seed += currentLessonId.charCodeAt(i);

  const picked = [];
  const cloned = [...candidates];
  const count = seed % 2 === 0 ? 3 : 4;
  while (picked.length < count && cloned.length > 0) {
    const idx = (seed + picked.length * 7) % cloned.length;
    const q = cloned.splice(idx, 1)[0];
    picked.push({
      id: `warmup-${currentLessonId}-${picked.length + 1}`,
      stem: q.stem,
      choices: q.choices,
      correctIndex: q.correctIndex,
      explanation: q.explanation || "Review previous lesson concept.",
    });
  }
  return picked;
}

/**
 * Plan (and optionally write) warmup blocks.
 *
 * Default is report-only. Warmups on disk are authored source of truth
 * (spirals, softened Unit 1, catch-up retargets). A bare `node scripts/generate-warmups.mjs`
 * used to rewrite every config. Pass `--write` to mutate.
 */
export function generate({ write = false, lessonsDir = LESSONS_DIR, bankPath = BANK_PATH } = {}) {
  const bank = JSON.parse(readFileSync(bankPath, "utf8"));
  const questions = bank.questions;
  const questionsByLesson = {};
  for (const q of questions) {
    if (!q.lessonId) continue;
    if (!questionsByLesson[q.lessonId]) questionsByLesson[q.lessonId] = [];
    questionsByLesson[q.lessonId].push(q);
  }

  const ids = wholeGroupLessonIds(lessonsDir);
  let countUpdated = 0;
  let wouldChange = 0;

  for (const dirName of readdirSync(lessonsDir)) {
    const configPath = join(lessonsDir, dirName, "config.json");
    if (!existsSync(configPath)) continue;

    try {
      const cfg = JSON.parse(readFileSync(configPath, "utf8"));
      const baseId = getBaseLessonId(dirName);
      const prevId = previousLessonId(ids, baseId);

      let prevTitle = `Lesson ${prevId}`;
      const prevConfigPath = join(lessonsDir, prevId, "config.json");
      if (existsSync(prevConfigPath)) {
        const prevCfg = JSON.parse(readFileSync(prevConfigPath, "utf8"));
        if (prevCfg.title) prevTitle = prevCfg.title;
      }

      const proposed = {
        title: "Warmup: Previous Lesson Check",
        prevLessonId: prevId,
        prevLessonTitle: prevTitle,
        questions: pickWarmupQuestions(questionsByLesson, questions, prevId, baseId),
      };
      if (JSON.stringify(cfg.warmup || null) !== JSON.stringify(proposed)) wouldChange++;

      if (!write) continue;

      cfg.warmup = proposed;
      writeFileSync(configPath, JSON.stringify(cfg, null, 2) + "\n");
      countUpdated++;
    } catch (err) {
      console.error(`Error updating ${configPath}:`, err.message);
    }
  }

  if (!write) {
    console.log(
      `--check: generator would rewrite warmup on ${wouldChange} config(s). ` +
        "Pass --write to mutate. On-disk warmups are the source of truth.",
    );
    return { wouldChange, countUpdated: 0, wrote: false };
  }

  console.log(
    `Successfully generated and injected 3-4 autograded Warmup questions into ${countUpdated} lesson configs!`,
  );
  return { wouldChange, countUpdated, wrote: true };
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  const write = process.argv.includes("--write");
  generate({ write });
}
